local ScriptLinks = {
    Part1 = "https://raw.githubusercontent.com/XASZD-NET/VORTEX_ENGINE_DELTA-2.5/refs/heads/main/UI/Lua/Part1_UICore.lua",
    Part2 = "https://raw.githubusercontent.com/XASZD-NET/VORTEX_ENGINE_DELTA-2.5/refs/heads/main/UI/Lua/Part2_ScriptUI1.lua",
    Part3 = "https://raw.githubusercontent.com/XASZD-NET/VORTEX_ENGINE_DELTA-2.5/refs/heads/main/UI/Lua/Part3_ScriptUI2.lua",
    Part4 = "https://raw.githubusercontent.com/XASZD-NET/VORTEX_ENGINE_DELTA-2.5/refs/heads/main/UI/Lua/Part4_MessageAndFunctionTab.lua",
    Part5 = "https://raw.githubusercontent.com/XASZD-NET/VORTEX_ENGINE_DELTA-2.5/refs/heads/main/UI/Lua/Part5_PingPongRelay.lua"
}

local function SafeLoadUrl(url)
    if type(url) ~= "string" or url == "" then
        return false
    end
    local ok, err = pcall(function()
        local source = game:HttpGet(url)
        local chunk = loadstring(source)
        if type(chunk) == "function" then
            chunk()
        end
    end)
    if not ok then
        warn("[UnifiedScript] โหลดลิงก์ไม่สำเร็จ: " .. tostring(url) .. " | Error: " .. tostring(err))
    end
    return ok
end

local LoadedParts = {}
for _, key in ipairs({ "Part1", "Part2", "Part3", "Part4", "Part5" }) do
    LoadedParts[key] = SafeLoadUrl(ScriptLinks[key])
end

